const recoveryArtifactsRetrievalFiles={"consistent_recovery_cut.py": "\"\"\"Actual SQLite backup/replay and immutable fixture objects; application journal, not database WAL.\"\"\"\nfrom contextlib import contextmanager\nimport hashlib\nimport json\nfrom pathlib import Path\nimport shutil\nimport sqlite3\nimport tempfile\n\n\n@contextmanager\ndef connect(path):\n    db = sqlite3.connect(path)\n    try:\n        with db:\n            yield db\n    finally:\n        db.close()\n\n\ndef digest(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef clone(source, destination):\n    with connect(source) as old, connect(destination) as new:\n        old.backup(new)\n\n\ndef problems(db, objects):\n    errors = []\n    for identity, key, expected in db.execute(\"SELECT id,object_key,sha256 FROM reports ORDER BY id\"):\n        path = objects / key\n        if not path.is_file():\n            errors.append({\"report\": identity, \"object\": key, \"reason\": \"missing_object_version\"})\n        elif digest(path.read_bytes()) != expected:\n            errors.append({\"report\": identity, \"object\": key, \"reason\": \"object_hash_mismatch\"})\n    return errors\n\n\ndef insert_event(db, event):\n    db.execute(\"INSERT INTO reports VALUES(?,?,?,?,?)\", (event[\"report\"], \"A\", event[\"seq\"], event[\"object\"], event[\"sha256\"]))\n    db.execute(\"UPDATE progress SET seq=?,minute=?\", (event[\"seq\"], event[\"minute\"]))\n\n\ndef recover(backup, target, events, objects, require_objects=True):\n    clone(backup, target)\n    stopped = None\n    with connect(target) as db:\n        if problems(db, objects):\n            raise ValueError(\"baseline_not_usable\")\n        for event in events:\n            seq = db.execute(\"SELECT seq FROM progress\").fetchone()[0]\n            if event[\"seq\"] != seq+1:\n                stopped = {\"expected_seq\": seq+1, \"received_seq\": event[\"seq\"], \"reason\": \"journal_gap\"}\n                break\n            try:\n                with db:\n                    insert_event(db, event)\n                    errors = problems(db, objects)\n                    if require_objects and errors:\n                        raise ValueError(json.dumps(errors))\n            except ValueError as error:\n                stopped = {\"at_seq\": event[\"seq\"], \"reason\": \"business_state_incomplete\", \"details\": json.loads(str(error))}\n                break\n        seq, minute = db.execute(\"SELECT seq,minute FROM progress\").fetchone()\n        issues = problems(db, objects)\n        report_ids = [row[0] for row in db.execute(\"SELECT id FROM reports WHERE tenant='A' ORDER BY id\")]\n        unreadable = {issue[\"report\"] for issue in issues}\n        readable_ids = [identity for identity in report_ids if identity not in unreadable]\n        forbidden = db.execute(\"SELECT object_key FROM reports WHERE tenant=? AND id=?\", (\"A\", \"B-report\")).fetchone()\n        physical = db.execute(\"PRAGMA integrity_check\").fetchone()[0]\n    return {\"seq\": seq, \"minute\": minute, \"gap_minutes_at_noon\": 720-minute,\n            \"database_point_within_15_minutes\": 720-minute <= 15,\n            \"business_RPO_pass\": not issues and 720-minute <= 15, \"physical_integrity\": physical,\n            \"business_problems\": issues, \"A_report_rows\": report_ids, \"A_readable_reports\": readable_ids,\n            \"A_cannot_query_B_report\": forbidden is None, \"stopped\": stopped}\n\n\ndef main():\n    with tempfile.TemporaryDirectory(prefix=\"infra-recovery-cut-\") as temporary:\n        root = Path(temporary)\n        source_objects = root / \"source-objects\"\n        source_objects.mkdir()\n        contents = {\"object-v1\": b\"A report 1\", \"object-v2\": b\"A report 2\",\n                    \"object-v3\": b\"A report 3\", \"object-v4\": b\"A report 4\", \"object-B\": b\"fixture B\"}\n        for name, content in contents.items():\n            (source_objects / name).write_bytes(content)\n        source, backup = root / \"source.db\", root / \"baseline.db\"\n        with connect(source) as db:\n            db.executescript(\"CREATE TABLE reports(id TEXT PRIMARY KEY,tenant TEXT,revision INT,object_key TEXT,sha256 TEXT);\"\n                             \"CREATE TABLE progress(seq INT,minute INT); INSERT INTO progress VALUES(100,690);\")\n            db.executemany(\"INSERT INTO reports VALUES(?,?,?,?,?)\", [\n                (\"R1\", \"A\", 100, \"object-v1\", digest(contents[\"object-v1\"])),\n                (\"B-report\", \"B\", 100, \"object-B\", digest(contents[\"object-B\"]))])\n        clone(source, backup)\n        events = [{\"seq\": seq, \"minute\": minute, \"report\": identity, \"object\": key, \"sha256\": digest(contents[key])}\n                  for seq, minute, identity, key in [(101, 702, \"R2\", \"object-v2\"), (102, 714, \"R3\", \"object-v3\"), (103, 717, \"R4\", \"object-v4\")]]\n        journal = root / \"application-journal.jsonl\"\n        with connect(source) as db, journal.open(\"w\") as log:\n            for event in events:\n                with db:\n                    insert_event(db, event)\n                log.write(json.dumps(event)+\"\\n\")\n        events = [json.loads(line) for line in journal.read_text().splitlines()]\n\n        partial_objects = root / \"partial-objects\"\n        shutil.copytree(source_objects, partial_objects)\n        (partial_objects / \"object-v3\").unlink()  # Declared recovery-material failure in a disposable fixture.\n        naive = recover(backup, root / \"naive.db\", events, partial_objects, False)\n        cut = recover(backup, root / \"cut.db\", events, partial_objects)\n        complete = recover(backup, root / \"complete.db\", events, source_objects)\n        missing_log = recover(backup, root / \"log-gap.db\", [events[0], events[2]], source_objects)\n        corrupt_objects = root / \"corrupt-objects\"\n        shutil.copytree(source_objects, corrupt_objects)\n        (corrupt_objects / \"object-v2\").write_bytes(b\"changed fixture bytes\")\n        corrupt = recover(backup, root / \"corrupt.db\", events, corrupt_objects)\n        assert naive[\"seq\"] == 103 and naive[\"physical_integrity\"] == \"ok\"\n        assert naive[\"business_problems\"] == [{\"report\": \"R3\", \"object\": \"object-v3\", \"reason\": \"missing_object_version\"}]\n        assert cut[\"seq\"] == 101 and cut[\"gap_minutes_at_noon\"] == 18 and not cut[\"business_RPO_pass\"]\n        assert cut[\"A_readable_reports\"] == [\"R1\", \"R2\"] and not cut[\"business_problems\"]\n        assert naive[\"A_report_rows\"] == [\"R1\", \"R2\", \"R3\", \"R4\"]\n        assert naive[\"A_readable_reports\"] == [\"R1\", \"R2\", \"R4\"]\n        assert complete[\"seq\"] == 103 and complete[\"gap_minutes_at_noon\"] == 3 and complete[\"business_RPO_pass\"]\n        assert naive[\"database_point_within_15_minutes\"] and not naive[\"business_RPO_pass\"]\n        assert missing_log[\"seq\"] == 101 and missing_log[\"stopped\"][\"reason\"] == \"journal_gap\"\n        assert corrupt[\"seq\"] == 100 and corrupt[\"gap_minutes_at_noon\"] == 30\n        assert all(case[\"A_cannot_query_B_report\"] for case in [naive, cut, complete, missing_log, corrupt])\n    print(json.dumps({\"sqlite\": sqlite3.sqlite_version, \"failure_minute\": 720, \"baseline_minute\": 690,\n                      \"commits\": [{k: e[k] for k in [\"seq\", \"minute\", \"report\", \"object\"]} for e in events],\n                      \"naive_latest_database\": naive, \"last_complete_business_prefix\": cut,\n                      \"all_materials_present\": complete, \"missing_log_segment\": missing_log,\n                      \"corrupt_object\": corrupt,\n                      \"scope\": \"actual_SQLite_backup_and_fixture_object_validation_with_application_log_not_PostgreSQL_WAL_or_cloud_DR\",\n                      \"limits\": [\"minute values are declared teaching times, not measured restore durations\",\n                                 \"application journal is constructed in the fixture; no power-loss durability claim\",\n                                 \"recovery-point age is not a count of lost reports; row presence alone does not prove readable content\",\n                                 \"tenant predicate tests this consumer query, not a deployed IAM system\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "recovered_effects.py": "\"\"\"Actual SQLite outbox restore and HTTP effect receipts, with receiver-owned generation checks.\"\"\"\nfrom contextlib import contextmanager\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\nimport threading\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\nfrom urllib.error import HTTPError\nfrom urllib.request import Request, ProxyHandler, build_opener\n\n\n@contextmanager\ndef connect(path):\n    db = sqlite3.connect(path)\n    try:\n        with db:\n            yield db\n    finally:\n        db.close()\n\n\ndef copy_database(source, target):\n    with connect(source) as old, connect(target) as new:\n        old.backup(new)\n\n\ndef apply(path, payload):\n    with connect(path) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        epoch = db.execute(\"SELECT epoch FROM owner\").fetchone()[0]\n        if payload[\"epoch\"] != epoch:\n            return 409, {\"error\": \"stale_owner_generation\"}\n        row = db.execute(\"SELECT total FROM effects WHERE event_id=?\", (payload[\"event_id\"],)).fetchone()\n        if row is not None:\n            if row[0] != payload[\"total\"]:\n                return 409, {\"error\": \"intent_conflict\"}\n            return 200, {\"duplicate\": True, \"event_id\": payload[\"event_id\"], \"total\": row[0]}\n        db.execute(\"INSERT INTO effects VALUES(?,?)\", (payload[\"event_id\"], payload[\"total\"]))\n    return 200, {\"duplicate\": False, \"event_id\": payload[\"event_id\"], \"total\": payload[\"total\"]}\n\n\ndef main():\n    with tempfile.TemporaryDirectory(prefix=\"infra-recovered-effects-\") as temporary:\n        root = Path(temporary)\n        receiver, application = root / \"receiver.db\", root / \"application.db\"\n        backup, restored = root / \"application-backup.db\", root / \"application-restored.db\"\n        with connect(receiver) as db:\n            db.executescript(\"CREATE TABLE owner(epoch INT); INSERT INTO owner VALUES(1);\"\n                             \"CREATE TABLE effects(event_id TEXT PRIMARY KEY,total INT);\")\n        with connect(application) as db:\n            db.executescript(\"CREATE TABLE outbox(event_id TEXT PRIMARY KEY,total INT,state TEXT);\"\n                             \"INSERT INTO outbox VALUES('notify-R27',37,'PENDING');\")\n        copy_database(application, backup)\n        state = {\"lose_first_response\": True}\n\n        class Handler(BaseHTTPRequestHandler):\n            def log_message(self, *args):\n                pass\n\n            def do_POST(self):\n                value = json.loads(self.rfile.read(int(self.headers[\"Content-Length\"])))\n                assert set(value) == {\"event_id\", \"total\", \"epoch\"}\n                assert type(value[\"event_id\"]) is str and all(type(value[k]) is int for k in [\"total\", \"epoch\"])\n                status, body = apply(receiver, value)\n                if status == 200 and not body[\"duplicate\"] and state[\"lose_first_response\"]:\n                    state[\"lose_first_response\"] = False\n                    status, body = 503, {\"error\": \"injected_after_commit\"}\n                payload = json.dumps(body).encode()\n                self.send_response(status)\n                self.send_header(\"Content-Type\", \"application/json\")\n                self.send_header(\"Content-Length\", str(len(payload)))\n                self.end_headers()\n                self.wfile.write(payload)\n\n        server = HTTPServer((\"127.0.0.1\", 0), Handler)\n        thread = threading.Thread(target=server.serve_forever, kwargs={\"poll_interval\": .01})\n        thread.start()\n        opener = build_opener(ProxyHandler({}))\n\n        def request(identity, total, epoch):\n            payload = json.dumps({\"event_id\": identity, \"total\": total, \"epoch\": epoch}).encode()\n            req = Request(\"http://127.0.0.1:\"+str(server.server_port)+\"/effects\", payload, {\"Content-Type\": \"application/json\"})\n            try:\n                with opener.open(req, timeout=3) as response:\n                    return response.status, json.load(response)\n            except HTTPError as error:\n                return error.code, json.load(error)\n\n        try:\n            lost_status, _ = request(\"notify-R27\", 37, 1)\n            assert lost_status == 503\n            confirmed_status, confirmation = request(\"notify-R27\", 37, 1)\n            assert confirmed_status == 200 and confirmation[\"duplicate\"]\n            with connect(application) as db:\n                db.execute(\"UPDATE outbox SET state='DONE'\")\n            copy_database(backup, restored)\n            with connect(restored) as db:\n                before = db.execute(\"SELECT state FROM outbox\").fetchone()[0]\n            assert before == \"PENDING\"\n            # Trusted fixture controller changes the receiver's authority, outside the restored application DB.\n            with connect(receiver) as db:\n                db.execute(\"UPDATE owner SET epoch=2\")\n            stale_status, stale_body = request(\"late-old-owner\", 9, 1)\n            replay_status, replay = request(\"notify-R27\", 37, 2)\n            conflict_status, conflict_body = request(\"notify-R27\", 38, 2)\n            assert stale_status == 409 and stale_body[\"error\"] == \"stale_owner_generation\"\n            assert replay_status == 200 and replay[\"duplicate\"] and replay[\"total\"] == 37\n            assert conflict_status == 409 and conflict_body[\"error\"] == \"intent_conflict\"\n            with connect(restored) as db:\n                db.execute(\"UPDATE outbox SET state='DONE' WHERE event_id=?\", (replay[\"event_id\"],))\n                after = db.execute(\"SELECT state FROM outbox\").fetchone()[0]\n            with connect(receiver) as db:\n                effects = db.execute(\"SELECT event_id,total FROM effects ORDER BY event_id\").fetchall()\n            assert effects == [(\"notify-R27\", 37)] and after == \"DONE\"\n            negative = root / \"negative-receiver.db\"\n            copy_database(receiver, negative)\n            naive_status, naive_receipt = apply(negative, {\"event_id\": \"notify-R27-new-key\", \"total\": 37, \"epoch\": 2})\n            with connect(negative) as db:\n                negative_count = db.execute(\"SELECT COUNT(*) FROM effects\").fetchone()[0]\n            assert naive_status == 200 and not naive_receipt[\"duplicate\"] and negative_count == 2\n        finally:\n            server.shutdown()\n            server.server_close()\n            thread.join(timeout=5)\n            assert not thread.is_alive()\n    print(json.dumps({\"first_http_after_effect_commit\": lost_status,\n                      \"confirmed_before_restore\": confirmation, \"restored_outbox_before\": before,\n                      \"receiver_generation_after_promotion\": 2, \"old_owner_request\": {\"status\": stale_status, **stale_body},\n                      \"recovered_replay\": {\"status\": replay_status, **replay},\n                      \"same_id_changed_intent\": {\"status\": conflict_status, **conflict_body},\n                      \"restored_outbox_after\": after, \"positive_effects\": effects,\n                      \"new_key_negative_effect_count\": negative_count,\n                      \"scope\": \"actual_local_HTTP_and_SQLite_restore_receipts_generation_not_cloud_failover_or_production_auth\",\n                      \"limits\": [\"owner generation and effect mutation are checked in the receiver's one DB transaction\",\n                                 \"authority DB is not restored with the application; promotion is a trusted fixture action\",\n                                 \"an epoch number is not a credential; real authentication and authorized promotion are outside this fixture\",\n                                 \"restoring application state does not undo the receiver's existing external effect\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "artifact_bundle.py": "\"\"\"Actual CPU/Safetensors bundles: byte integrity, shape, semantic contract and pointer CAS.\"\"\"\nimport hashlib\nimport json\nfrom pathlib import Path\nimport shutil\nimport sqlite3\nimport tempfile\n\nimport safetensors\nfrom safetensors.torch import save_file, load as load_tensor_bytes\nimport torch\nfrom torch import nn\n\nMEMBERS = {\"model.json\", \"tokenizer.json\", \"weights.safetensors\"}\n\n\ndef digest(data):\n    return hashlib.sha256(data).hexdigest()\n\n\nclass Toy(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.embedding = nn.Embedding(3, 1)\n        self.readout = nn.Linear(1, 1)\n\n    def forward(self, ids):\n        return self.readout(self.embedding(ids))\n\n\ndef make_bundle(root, version, swap_vocab=False, swap_rows=False):\n    folder = root / version\n    folder.mkdir()\n    model = Toy()\n    with torch.no_grad():\n        model.embedding.weight.copy_(torch.tensor([[2.], [1.], [0.]]) if swap_rows else torch.tensor([[1.], [2.], [0.]]))\n        model.readout.weight.fill_(1)\n        model.readout.bias.zero_()\n    save_file({k: v.detach().contiguous() for k, v in model.state_dict().items()}, str(folder / \"weights.safetensors\"))\n    (folder / \"model.json\").write_text(json.dumps({\"architecture\": \"toy-v1\", \"vocab_size\": 3, \"width\": 1}, sort_keys=True))\n    vocab = {\"A\": 1 if swap_vocab else 0, \"B\": 0 if swap_vocab else 1, \"<unk>\": 2}\n    (folder / \"tokenizer.json\").write_text(json.dumps(vocab, sort_keys=True))\n    manifest = {\"format\": \"toy-bundle-v1\", \"version\": version,\n                \"runtime\": {\"torch\": torch.__version__, \"safetensors\": safetensors.__version__,\n                            \"loader_sha256\": digest(Path(__file__).read_bytes())},\n                \"files\": {name: {\"bytes\": (folder/name).stat().st_size, \"sha256\": digest((folder/name).read_bytes())}\n                          for name in sorted(MEMBERS)}}\n    (folder / \"manifest.json\").write_text(json.dumps(manifest, sort_keys=True))\n    return folder\n\n\ndef load_bundle(folder):\n    manifest_bytes = (folder / \"manifest.json\").read_bytes()\n    manifest = json.loads(manifest_bytes)\n    if manifest[\"format\"] != \"toy-bundle-v1\" or set(manifest[\"files\"]) != MEMBERS:\n        raise ValueError(\"bundle_members_or_format\")\n    if manifest[\"runtime\"] != {\"torch\": torch.__version__, \"safetensors\": safetensors.__version__,\n                              \"loader_sha256\": digest(Path(__file__).read_bytes())}:\n        raise ValueError(\"runtime_contract\")\n    # Keep the verified bytes. Deserialization does not reopen a changeable path.\n    verified = {}\n    for name, expected in manifest[\"files\"].items():\n        path = folder / name\n        if path.is_symlink() or path.stat().st_size > 65536:\n            raise ValueError(\"fixture_file_policy\")\n        value = path.read_bytes()\n        if len(value) != expected[\"bytes\"] or digest(value) != expected[\"sha256\"]:\n            raise ValueError(\"member_digest_mismatch\")\n        verified[name] = value\n    if json.loads(verified[\"model.json\"]) != {\"architecture\": \"toy-v1\", \"vocab_size\": 3, \"width\": 1}:\n        raise ValueError(\"architecture_contract\")\n    vocab = json.loads(verified[\"tokenizer.json\"])\n    if set(vocab) != {\"A\", \"B\", \"<unk>\"} or any(type(v) is not int for v in vocab.values()) or set(vocab.values()) != {0, 1, 2}:\n        raise ValueError(\"vocabulary_shape\")\n    model = Toy()\n    state = load_tensor_bytes(verified[\"weights.safetensors\"])\n    model.load_state_dict(state, strict=True)\n    model.eval()\n    return {\"version\": manifest[\"version\"], \"manifest_sha256\": digest(manifest_bytes),\n            \"model\": model, \"vocab\": vocab, \"files\": manifest[\"files\"],\n            \"tensor_shapes\": {k: list(v.shape) for k, v in state.items()}}\n\n\ndef predict(bundle, text):\n    identity = bundle[\"vocab\"].get(text, bundle[\"vocab\"][\"<unk>\"])\n    with torch.no_grad():\n        return bundle[\"model\"](torch.tensor([identity])).item()\n\n\ndef gate(bundle):\n    values = {text: predict(bundle, text) for text in [\"A\", \"B\", \"?\"]}\n    expected = {\"A\": 1., \"B\": 2., \"?\": 0.}\n    return {\"outputs\": values, \"passed\": all(abs(values[k]-expected[k]) < 1e-8 for k in expected)}\n\n\ndef pointer(db):\n    version, generation, sha = db.execute(\"SELECT version,generation,manifest_sha FROM route WHERE id=1\").fetchone()\n    return {\"version\": version, \"generation\": generation, \"manifest_sha256\": sha}\n\n\ndef activate(db, expected, candidate):\n    if not gate(candidate)[\"passed\"]:\n        return \"semantic_gate_rejected\"\n    with db:\n        changed = db.execute(\"UPDATE route SET version=?,generation=generation+1,manifest_sha=? \"\n                             \"WHERE id=1 AND version=? AND generation=? AND manifest_sha=?\",\n                             (candidate[\"version\"], candidate[\"manifest_sha256\"], expected[\"version\"],\n                              expected[\"generation\"], expected[\"manifest_sha256\"])).rowcount\n    return \"activated\" if changed else \"stale_pointer\"\n\n\ndef main():\n    torch.set_num_threads(1)\n    with tempfile.TemporaryDirectory(prefix=\"infra-bundle-\") as temporary:\n        root = Path(temporary)\n        paths = {\"r17\": make_bundle(root, \"r17\"), \"r18\": make_bundle(root, \"r18\", True, False),\n                 \"r19\": make_bundle(root, \"r19\", True, True)}\n        bundles = {name: load_bundle(path) for name, path in paths.items()}\n        assert bundles[\"r17\"][\"tensor_shapes\"] == bundles[\"r18\"][\"tensor_shapes\"] == bundles[\"r19\"][\"tensor_shapes\"]\n        assert gate(bundles[\"r17\"])[\"passed\"] and not gate(bundles[\"r18\"])[\"passed\"] and gate(bundles[\"r19\"])[\"passed\"]\n        db = sqlite3.connect(root / \"route.db\")\n        db.execute(\"CREATE TABLE route(id INT PRIMARY KEY,version TEXT,generation INT,manifest_sha TEXT)\")\n        db.execute(\"INSERT INTO route VALUES(1,'r17',1,?)\", (bundles[\"r17\"][\"manifest_sha256\"],))\n        db.commit()\n        initial = pointer(db)\n        bad_candidate = activate(db, initial, bundles[\"r18\"])\n        assert bad_candidate == \"semantic_gate_rejected\" and pointer(db) == initial\n        in_flight = bundles[\"r17\"]\n        assert activate(db, initial, bundles[\"r19\"]) == \"activated\"\n        after_switch = pointer(db)\n        stale = activate(db, initial, bundles[\"r17\"])\n        assert stale == \"stale_pointer\" and pointer(db) == after_switch\n        mixed = {\"model\": bundles[\"r19\"][\"model\"], \"vocab\": bundles[\"r17\"][\"vocab\"]}\n        assert not gate(mixed)[\"passed\"]\n        broken = root / \"broken-r17\"\n        shutil.copytree(paths[\"r17\"], broken)\n        (broken / \"tokenizer.json\").unlink()\n        missing_rejected = False\n        try:\n            load_bundle(broken)\n        except FileNotFoundError:\n            missing_rejected = True\n        assert missing_rejected and pointer(db) == after_switch\n        tampered = root / \"tampered-r17\"\n        shutil.copytree(paths[\"r17\"], tampered)\n        weights = tampered / \"weights.safetensors\"\n        value = bytearray(weights.read_bytes())\n        value[-1] ^= 1\n        weights.write_bytes(value)\n        tamper_rejected = False\n        try:\n            load_bundle(tampered)\n        except ValueError as error:\n            tamper_rejected = str(error) == \"member_digest_mismatch\"\n        assert tamper_rejected\n        assert activate(db, after_switch, load_bundle(paths[\"r17\"])) == \"activated\"\n        after_rollback = pointer(db)\n        assert after_switch[\"version\"] == \"r19\" and after_switch[\"generation\"] == 2\n        assert after_rollback[\"version\"] == \"r17\" and after_rollback[\"generation\"] == 3\n        report = {\"torch\": torch.__version__, \"safetensors\": safetensors.__version__, \"device\": \"cpu\",\n                  \"bundle_members\": sorted(MEMBERS), \"tensor_shapes\": bundles[\"r17\"][\"tensor_shapes\"],\n                  \"gates\": {name: gate(bundle) for name, bundle in bundles.items()},\n                  \"r18_integrity_and_shapes_passed\": True, \"r18_activation\": bad_candidate,\n                  \"initial_pointer\": initial, \"after_switch\": after_switch,\n                  \"stale_publisher\": stale, \"mixed_bundle_gate\": gate(mixed),\n                  \"in_flight_pinned_version\": in_flight[\"version\"], \"in_flight_A\": predict(in_flight, \"A\"),\n                  \"missing_rollback_member_rejected\": missing_rejected, \"tamper_rejected_before_tensor_load\": tamper_rejected,\n                  \"after_rollback\": after_rollback,\n                  \"scope\": \"actual_CPU_Safetensors_and_SQLite_pointer_fixture_not_LLM_quality_GPU_or_online_canary\",\n                  \"limits\": [\"digests prove byte identity, not publisher trust or model usefulness\",\n                             \"small fixture reads verified bytes into RAM; large models need appropriate immutable staging/loading\",\n                             \"route CAS is local reference; no distributed load balancer or in-flight drain test\",\n                             \"semantic labels A=1 B=2 are a fixed contract, not a real model benchmark\"]}\n        db.close()\n    print(json.dumps(report, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "chinese_fts_rrf.py": "\"\"\"Actual Chinese SQLite FTS5/BM25, declared second ranker, exact RRF and fixed graded labels.\"\"\"\nfrom fractions import Fraction\nimport json\nimport math\nimport re\nimport sqlite3\n\nDOCS = [\n    (1, \"a-backup\", \"A\", 1, 1, \"数据库备份支持恢复。恢复前校验日志链。\"),\n    (2, \"a-dr\", \"A\", 1, 1, \"灾难恢复要求验证备份和附件一致。\"),\n    (3, \"a-cache\", \"A\", 1, 1, \"缓存预热减少冷启动延迟。\"),\n    (4, \"a-plan\", \"A\", 1, 1, \"备份方案应跨故障域，并核对恢复点。\"),\n    (5, \"a-old\", \"A\", 1, 0, \"数据库备份恢复只需重启主机。\"),\n    (6, \"b-private\", \"B\", 1, 1, \"数据库备份恢复涉及乙租户内部记录。\"),\n    (7, \"a-network\", \"A\", 1, 1, \"网络路由与名称解析决定请求路径。\"),\n    (8, \"a-archive\", \"A\", 1, 1, \"查找旧数据时，先验证归档是否能重放。\"),\n]\nGRADES = {\"a-backup\": 3, \"a-dr\": 2, \"a-plan\": 1, \"a-archive\": 2}\n\n\ndef tokens(text):\n    result = []\n    for part in re.findall(r\"[\\u4e00-\\u9fff]+|[A-Za-z0-9_]+\", text):\n        if re.fullmatch(r\"[\\u4e00-\\u9fff]+\", part):\n            result.extend(part[i:i+2] for i in range(len(part)-1)) if len(part)>1 else result.append(part)\n        else:\n            result.append(part.lower())\n    return result\n\n\ndef query_syntax(text):\n    terms = list(dict.fromkeys(tokens(text)))\n    return \" OR \".join('\"'+term+'\"' for term in terms)\n\n\ndef search(db, text, require_fresh=True):\n    clause = \" AND CAST(segmented.version AS INT)=d.version\" if require_fresh else \"\"\n    sql = (\"SELECT d.doc_id,bm25(segmented),d.version,segmented.version FROM segmented JOIN docs d ON d.id=segmented.rowid \"\n           \"WHERE segmented MATCH ? AND d.tenant=? AND d.current=1\"+clause+\" ORDER BY bm25(segmented),d.doc_id LIMIT ?\")\n    return [{\"id\": identity, \"bm25\": score, \"document_version\": current, \"index_version\": int(indexed)}\n            for identity, score, current, indexed in db.execute(sql, (query_syntax(text), \"A\", 8))]\n\n\ndef rrf(rankings, constant=60):\n    if type(constant) is not int or constant < 1:\n        raise ValueError(\"positive integer rank constant required\")\n    scores, ranks = {}, {}\n    for name, values in rankings.items():\n        if len(set(values)) != len(values):\n            raise ValueError(\"duplicate_document_in_one_ranker\")\n        for position, identity in enumerate(values, 1):\n            scores[identity] = scores.get(identity, Fraction(0)) + Fraction(1, constant+position)\n            ranks.setdefault(identity, {})[name] = position\n    return [{\"id\": identity, \"score\": float(scores[identity]), \"exact\": str(scores[identity]), \"ranks\": ranks[identity]}\n            for identity in sorted(scores, key=lambda identity: (-scores[identity], identity))]\n\n\ndef metric(ranked, count=3):\n    chosen = ranked[:count]\n    relevant = {identity for identity, grade in GRADES.items() if grade>0}\n    hits = len(set(chosen)&relevant)\n    dcg = sum((2**GRADES.get(identity, 0)-1)/math.log2(position+1) for position, identity in enumerate(chosen, 1))\n    ideal = sum((2**grade-1)/math.log2(position+1)\n                for position, grade in enumerate(sorted(GRADES.values(), reverse=True)[:count], 1))\n    first = next((i for i, identity in enumerate(chosen, 1) if identity in relevant), None)\n    return {\"precision_at_3\": hits/count, \"recall_at_3\": hits/len(relevant),\n            \"reciprocal_rank_at_3\": 1/first if first else 0, \"dcg_at_3\": dcg, \"ideal_dcg_at_3\": ideal,\n            \"ndcg_at_3\": dcg/ideal, \"label_source\": \"declared_teaching_grades_not_model_judgments\"}\n\n\ndef main():\n    db = sqlite3.connect(\":memory:\")\n    db.executescript(\"CREATE TABLE docs(id INT PRIMARY KEY,doc_id TEXT,tenant TEXT,version INT,current INT,body TEXT);\"\n                     \"CREATE VIRTUAL TABLE raw_index USING fts5(body,tokenize='unicode61');\"\n                     \"CREATE VIRTUAL TABLE segmented USING fts5(terms,version UNINDEXED,tokenize='unicode61');\"\n                     \"CREATE VIRTUAL TABLE raw_vocabulary USING fts5vocab(raw_index,'row');\")\n    db.executemany(\"INSERT INTO docs VALUES(?,?,?,?,?,?)\", DOCS)\n    for identity, _, _, version, _, body in DOCS:\n        db.execute(\"INSERT INTO raw_index(rowid,body) VALUES(?,?)\", (identity, body))\n        db.execute(\"INSERT INTO segmented(rowid,terms,version) VALUES(?,?,?)\", (identity, \" \".join(tokens(body)), version))\n    raw_hits = [row[0] for row in db.execute(\"SELECT rowid FROM raw_index WHERE raw_index MATCH ?\", (\"恢复\",))]\n    raw_term_present = db.execute(\"SELECT 1 FROM raw_vocabulary WHERE term=?\", (\"恢复\",)).fetchone() is not None\n    lexical = search(db, \"数据库恢复\")\n    assert not raw_hits and not raw_term_present\n    assert \"a-backup\" in [r[\"id\"] for r in lexical]\n    assert not ({r[\"id\"] for r in lexical}&{\"a-old\", \"b-private\"})\n    assert [r[\"bm25\"] for r in lexical] == sorted(r[\"bm25\"] for r in lexical)\n    second = [\"a-archive\", \"a-backup\", \"a-plan\"]  # Declared second-ranker result, not an embedding inference.\n    fused = rrf({\"lexical\": [r[\"id\"] for r in lexical], \"declared_second\": second})\n    duplicate_rejected = False\n    try:\n        rrf({\"bad\": [\"a-backup\", \"a-backup\"]})\n    except ValueError:\n        duplicate_rejected = True\n    assert duplicate_rejected\n    db.execute(\"UPDATE docs SET version=2,body=? WHERE doc_id='a-backup'\", (\"数据库恢复必须先校验版本二日志。\",))\n    unsafe_stale = search(db, \"数据库恢复\", False)\n    stale_row = next(row for row in unsafe_stale if row[\"id\"]==\"a-backup\")\n    safe_stale = search(db, \"数据库恢复\", True)\n    assert stale_row[\"document_version\"] == 2 and stale_row[\"index_version\"] == 1\n    assert \"a-backup\" not in [r[\"id\"] for r in safe_stale]\n    body = db.execute(\"SELECT body FROM docs WHERE doc_id='a-backup'\").fetchone()[0]\n    db.execute(\"UPDATE segmented SET terms=?,version=2 WHERE rowid=1\", (\" \".join(tokens(body)),))\n    repaired = next(row for row in search(db, \"数据库恢复\") if row[\"id\"]==\"a-backup\")\n    assert repaired[\"document_version\"] == repaired[\"index_version\"] == 2\n    report = {\"sqlite\": sqlite3.sqlite_version, \"documents\": len(DOCS), \"raw_query\": \"恢复\",\n              \"unicode61_raw_hits\": raw_hits, \"raw_has_standalone_query_term\": raw_term_present,\n              \"query\": \"数据库恢复\", \"query_terms\": tokens(\"数据库恢复\"), \"query_expression\": query_syntax(\"数据库恢复\"),\n              \"actual_lexical_results\": lexical, \"declared_second_ranker\": second,\n              \"rank_constant\": 60, \"rrf_results\": fused, \"grades\": GRADES,\n              \"lexical_metrics\": metric([r[\"id\"] for r in lexical]), \"rrf_metrics\": metric([r[\"id\"] for r in fused]),\n              \"duplicate_ranker_input_rejected\": duplicate_rejected,\n              \"stale_index_without_check\": stale_row, \"stale_index_excluded_with_check\": True,\n              \"after_reindex\": repaired,\n              \"scope\": \"actual_SQLite_FTS5_BM25_plus_declared_second_order_RRF_not_embedding_LLM_or_vector_database\",\n              \"limits\": [\"character bigrams are a teaching tokenizer, not a general Chinese linguistic analyzer\",\n                         \"tenant/current filters precede LIMIT in SQL semantics; corpus-level BM25 statistics remain shared\",\n                         \"real access revocation and body-delivery tests remain in the separate retrieval_pipeline experiment\",\n                         \"graded relevance is a fixed example, not a real retrieval benchmark\"]}\n    db.close()\n    print(json.dumps(report, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "requirements-model.txt": "torch==2.5.1\nsafetensors==0.8.0\n"};
